          <div className="section-bar"><div className="section-title"><h2>Game slate</h2><span>{filtered.length}</span>{inspectSource&&verificationPending&&<Badge tone="amber">Independent check pending</Badge>}</div><div className="slate-tools"><div className="search-wrap"><Search size={16}/><input aria-label="Search teams or matchups" placeholder="Search teams or matchups…" value={query} onChange={e=>setQuery(e.target.value)}/>{query&&<button aria-label="Clear search" onClick={()=>setQuery('')}><X size={14}/></button>}</div><label className="select-wrap filter-select"><Filter size={14}/><select aria-label="Game status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="all">All games</option><option value="upcoming">Upcoming</option><option value="completed">Completed</option><option value="live">Live</option><option value="postponed">Postponed</option><option value="canceled">Canceled</option></select><ChevronDown size={13}/></label><div className="view-switch"><button className={view==='grid'?'selected':''} aria-label="Grid view" aria-pressed={view==='grid'} onClick={()=>setView('grid')}><Grid2X2 size={16}/></button><button className={view==='list'?'selected':''} aria-label="List view" aria-pressed={view==='list'} onClick={()=>setView('list')}><List size={17}/></button></div></div></div>
